def goodness(ri, path, topics):
    """ri[path] = (num_docs, {topic: count}); stima dei documenti che trattano TUTTI i topic."""
    tot, cnt = ri[path]
    g = tot
    for t in topics:
        g *= cnt.get(t, 0) / tot
    return g

RI = {
    "B": (100,  {"DB": 20,  "N": 0,   "T": 10,  "L": 30}),
    "C": (1000, {"DB": 0,   "N": 300, "T": 0,   "L": 50}),
    "D": (200,  {"DB": 100, "N": 0,   "T": 100, "L": 150}),
}

def rank(ri, topics):
    return sorted(((goodness(ri, p, topics), p) for p in ri), reverse=True)

for q in (["DB", "L"], ["N"], ["T", "L"], ["DB", "T", "L"]):
    print(q, [(p, round(g, 2)) for g, p in rank(RI, q)])

import random
from collections import deque

def random_graph(n, d, seed=1):
    """Grafo casuale connesso: anello + archi casuali fino a grado medio circa d."""
    rnd = random.Random(seed)
    adj = {v: set() for v in range(n)}
    for v in range(n):                      # anello: garantisce la connessione
        adj[v].add((v + 1) % n); adj[(v + 1) % n].add(v)
    m_target = n * d // 2
    m = n
    while m < m_target:
        a, b = rnd.randrange(n), rnd.randrange(n)
        if a != b and b not in adj[a]:
            adj[a].add(b); adj[b].add(a); m += 1
    return adj

def flood(adj, src, ttl):
    """Flooding con TTL e ID: ritorna (messaggi inviati, nodi raggiunti, duplicati)."""
    seen = {src}
    msgs = dup = 0
    # (nodo, da_chi, ttl_residuo): la sorgente invia a tutti i vicini con ttl
    q = deque([(src, None, ttl)])
    while q:
        v, parent, t = q.popleft()
        if t == 0:
            continue
        for s in adj[v]:
            if s == parent:
                continue
            msgs += 1
            if s in seen:
                dup += 1          # ID già visto: scartato
            else:
                seen.add(s)
                q.append((s, v, t - 1))
    return msgs, len(seen), dup

adj = random_graph(1000, 6)
n = len(adj); m = sum(len(a) for a in adj.values()) // 2
print(f"n={n} m={m} grado medio={2*m/n:.1f}")
for ttl in range(1, 8):
    msgs, reached, dup = flood(adj, 0, ttl)
    print(f"TTL={ttl}: messaggi={msgs:5d} raggiunti={reached:4d} duplicati={dup:5d}")
msgs, reached, dup = flood(adj, 0, 10**9)
print("flooding completo:", msgs, "atteso 2m-n+1 =", 2*m - n + 1)

