import random
from collections import deque

def bfs_dist(adj, src):
    dist = {src: 0}; q = deque([src])
    while q:
        v = q.popleft()
        for s in adj[v]:
            if s not in dist:
                dist[s] = dist[v] + 1; q.append(s)
    return dist

def expanding_ring(adj, src, holders, seq):
    """Ritorna (TTL finale o None, elaborazioni naive, elaborazioni ottimizzate)."""
    dist = bfs_dist(adj, src)
    naive = 0
    for ttl in seq:
        ring = [v for v, d in dist.items() if d <= ttl]
        naive += len(ring)                  # naive: nuovo ID, tutti rielaborano
        if any(v in holders for v in ring):
            return ttl, naive, len(ring)    # ottimizzato: ognuno una volta sola
    return None, naive, len(ring)

def slide_tree(depth=5):
    """Albero delle slide 44-47: sorgente con 2 vicini, ogni altro nodo con 2 figli."""
    adj = {0: set()}; frontier = [0]; nid = 1
    for d in range(1, depth + 1):
        new = []
        for v in frontier:
            for _ in range(2):
                adj[nid] = {v}; adj[v].add(nid); new.append(nid); nid += 1
        frontier = new
    return adj

tree = slide_tree()
print("nodi albero:", len(tree))
print("{0,2,4,5}, nessun risultato:", expanding_ring(tree, 0, set(), [0, 2, 4, 5]))
print("{1,2,3,4,5}, nessun risultato:", expanding_ring(tree, 0, set(), [1, 2, 3, 4, 5]))

